// Minimal cron evaluator: matches the current minute against the agent's schedule_cron.
// Supports the 5-field cron format: minute hour day-of-month month day-of-week
// Each field accepts: *, number, comma list, range (a-b), step (*/n)
const rows = Array.isArray($json) ? $json : [];
const now = new Date();
const nowMinute = now.getUTCMinutes();
const nowHour = now.getUTCHours();
const nowDom = now.getUTCDate();
const nowMon = now.getUTCMonth() + 1;
const nowDow = now.getUTCDay(); // 0=sunday

function matchField(field, value, max) {
  if (field === '*') return true;
  for (const part of field.split(',')) {
    if (part.startsWith('*/')) {
      const step = parseInt(part.slice(2), 10);
      if (step > 0 && value % step === 0) return true;
    } else if (part.includes('-')) {
      const [a, b] = part.split('-').map(Number);
      if (value >= a && value <= b) return true;
    } else {
      if (parseInt(part, 10) === value) return true;
    }
  }
  return false;
}

function shouldRun(cron) {
  if (!cron) return false;
  const parts = cron.trim().split(/\s+/);
  if (parts.length !== 5) return false;
  // We allow a 5-min tolerance window (this workflow ticks every 5 min)
  for (let m = nowMinute - 4; m <= nowMinute; m++) {
    const minute = (m + 60) % 60;
    if (matchField(parts[0], minute, 60)
      && matchField(parts[1], nowHour, 24)
      && matchField(parts[2], nowDom, 31)
      && matchField(parts[3], nowMon, 12)
      && matchField(parts[4], nowDow, 7)) {
      return true;
    }
  }
  return false;
}

const toRun = [];
for (const r of rows) {
  if (!shouldRun(r.schedule_cron)) continue;
  // Avoid double-execution: skip if last_scheduled_run is within the last 4 minutes
  if (r.last_scheduled_run) {
    const ageMs = Date.now() - new Date(r.last_scheduled_run).getTime();
    if (ageMs < 4 * 60 * 1000) continue;
  }
  toRun.push({ json: r });
}
return toRun;
